def require_aio_error_artifact(family: Mapping[str, Any]) -> None:
    """Keep the one read-only AIO error observation outside AIO lifecycle work."""
    artifacts = require_verified_artifacts(
        family.get("verified_artifact"),
        "family[libc.posix-runtime].verified_artifact",
        family.get("status", ""),
    )
    matching = [entry for entry in artifacts if entry.get("id") == "static-c-aio-error"]
    require(
        len(matching) == 1,
        "libc.posix-runtime must contain exactly one static-c-aio-error artifact",
    )
    require(
        family.get("status") == "planned",
        "static-c-aio-error must not promote libc.posix-runtime",
    )
    artifact = matching[0]
    require(
        "capabilities" not in artifact,
        "static-c-aio-error must not claim a general runtime capability",
    )

    description = artifact.get("description")
    require(isinstance(description, str), "static-c-aio-error needs a description")
    for phrase in (
        "Private native x86 static `aio_error` observation C ABI artifact",
        "still-planned `libc.posix-runtime`",
        "archive-free `-nostdlib -static` candidate",
        "exactly one extracted `aio_error` object",
        "never `libc.a`",
        "x86 compiler-only `a_barrier()`",
        "volatile `struct aiocb::__err` load",
        "`& 0x7fffffff` mask",
        "168-byte align-8",
        "offset 112",
        "AIO request submission",
        "`aio_return`",
        "resolver/DNS/netdb",
        "public x86 support",
    ):
        require(phrase in description, f"static-c-aio-error description omits {phrase}")

    owners = set(
        nonempty_strings(artifact.get("source_owners"), "static-c-aio-error.source_owners")
    )
    for owner in (
        "compat/upstreams.toml",
        "compat/abi/musl-1.2.6/aarch64/libc.a.static.tsv",
        "compat/x86_64/headers-layouts.toml",
        "compat/x86_64/headers-layouts-foundation.toml",
        "libc/Cargo.toml",
        "libc/src/lib.rs",
        "libc/src/c_abi/x86_64/static_c_abi.rs",
        "libc/src/c_abi/x86_64/aio_error.rs",
        "include/aio.h",
        "compat/x86_64/aio_error_header_abi_probe.c",
        "compat/x86_64/aio_error_header_abi_probe.cpp",
        "compat/x86_64/run_aio_error_header_abi.sh",
        "compat/x86_64/static_c_abi_exports.txt",
        "compat/x86_64/libc_aio_error_probe.c",
        "compat/x86_64/libc_aio_error_start.S",
        "compat/x86_64/run_libc_aio_error.sh",
        "compat/x86_64/aarch64_parity_inventory.py",
        "compat/x86_64/aarch64_parity_inventory.json",
        "compat/x86_64/tests/test_parity_ledger.py",
        "compat/x86_64/tests/test_runner.py",
        "compat/x86_64/validate_parity_ledger.py",
        "compat/x86_64/README.md",
        "STATUS.md",
        "x86-64.md",
        "scripts/dev-x86_64.sh",
        "scripts/check_structure.py",
    ):
        require(owner in owners, f"static-c-aio-error source owners omit {owner}")

    prerequisites = nonempty_strings(
        artifact.get("x86_abi_prerequisites"), "static-c-aio-error.x86_abi_prerequisites"
    )
    require(
        any(
            "SysV AMD64 LP64" in item
            and "int aio_error(const struct aiocb *)" in item
            and "rdi" in item
            and "eax" in item
            and "168 bytes" in item
            and "offset 112" in item
            for item in prerequisites
        ),
        "static-c-aio-error must retain its pointer/int ABI and public layout",
    )
    require(
        any(
            "9fa28ece75d8a2191de7c5bb53bed224c5947417" in item
            and "src/aio/aio.c::aio_error" in item
            and "aio.lo" in item
            and "a_barrier" in item
            and "0x7fffffff" in item
            and "submitting, waiting for, or completing" in item
            for item in prerequisites
        ),
        "static-c-aio-error must retain its pinned-musl observation mapping",
    )
    require(
        any(
            "exactly one extracted `aio_error` object" in item
            and "never libc.a" in item
            and "no interpreter" in item
            and "TLS/errno" in item
            and "call, syscall" in item
            for item in prerequisites
        ),
        "static-c-aio-error must retain its archive-free static closure",
    )

    headers = nonempty_strings(
        artifact.get("x86_header_prerequisites"),
        "static-c-aio-error.x86_header_prerequisites",
    )
    require(
        any(
            "GNU-profile project `<aio.h>`" in item
            and "int aio_error(const struct aiocb *)" in item
            and "168-byte align-8 aiocb layout" in item
            and "volatile __err offset 112" in item
            and "_LARGEFILE64_SOURCE" in item
            and "unmangled C++ C linkage" in item
            and "incomplete" in item
            for item in headers
        ),
        "static-c-aio-error must retain its C/C++ aio header boundary",
    )

    exports = set(
        static_c_abi_export_names(
            ROOT / "compat" / "x86_64" / "static_c_abi_exports.txt"
        )
    )
    require(
        set(AIO_ERROR_SYMBOLS) <= exports,
        "static-c-aio-error must retain its selected export",
    )

    static_root = (
        ROOT / "libc" / "src" / "c_abi" / "x86_64" / "static_c_abi.rs"
    ).read_text(encoding="utf-8")
    require(
        '#[path = "aio_error.rs"]\nmod aio_error;' in static_root,
        "x86 static C ABI must compose the aio_error leaf",
    )
    implementation = (
        ROOT / "libc" / "src" / "c_abi" / "x86_64" / "aio_error.rs"
    ).read_text(encoding="utf-8")
    for snippet in (
        "9fa28ece75d8a2191de7c5bb53bed224c5947417",
        "src/aio/aio.c::aio_error",
        "const AIOCB_ERR_OFFSET: usize = 112",
        "const AIO_ERROR_MASK: c_int = 0x7fff_ffff",
        "compiler_fence(Ordering::SeqCst)",
        "asm!(",
        'pub unsafe extern "C" fn aio_error',
        "caller-provided AIO/external synchronization",
    ):
        require(snippet in implementation, f"aio_error leaf omits {snippet}")
    exported_functions = set(
        re.findall(
            r'(?m)^pub\s+unsafe\s+extern\s+"C"\s+fn\s+(\w+)\s*\(', implementation
        )
    )
    require(
        exported_functions == set(AIO_ERROR_SYMBOLS),
        "aio_error leaf must export only aio_error",
    )
    for forbidden in (
        "static mut",
        "raw_syscall",
        "__errno_location",
        "__h_errno_location",
        "getaddrinfo",
        "socket(",
        "std::",
        "alloc::",
        "crabc_core",
        "crabc_mimalloc",
        "fn aio_read",
        "fn aio_write",
        "fn aio_return",
        "fn aio_cancel",
        "fn aio_suspend",
        "fn aio_fsync",
        "fn lio_listio",
    ):
        require(forbidden not in implementation, f"aio_error leaf widens into {forbidden}")

    header_c = (
        ROOT / "compat" / "x86_64" / "aio_error_header_abi_probe.c"
    ).read_text(encoding="utf-8")
    header_cpp = (
        ROOT / "compat" / "x86_64" / "aio_error_header_abi_probe.cpp"
    ).read_text(encoding="utf-8")
    header_runner = (
        ROOT / "compat" / "x86_64" / "run_aio_error_header_abi.sh"
    ).read_text(encoding="utf-8")
    for snippet in (
        "#include <aio.h>",
        "aio_error_signature",
        "sizeof(struct aiocb) == 168",
        "__err) == 112",
    ):
        require(snippet in header_c, f"aio_error C header probe omits {snippet}")
        require(snippet in header_cpp, f"aio_error C++ header probe omits {snippet}")
    for snippet in (
        "-D_GNU_SOURCE",
        "-D_LARGEFILE64_SOURCE",
        "nm --undefined-only",
        "_Z.*aio_error",
        "project C aio_error header contract drifted",
    ):
        require(snippet in header_runner, f"aio_error header runner omits {snippet}")

    fixture = (
        ROOT / "compat" / "x86_64" / "libc_aio_error_probe.c"
    ).read_text(encoding="utf-8")
    for snippet in (
        "#include <aio.h>",
        "aio_error_signature",
        "sizeof(struct aiocb) == 168",
        "__err) == 112",
        "0x7fffffff",
        "-2147483647 - 1",
        "CRABC_AIO_ERROR_FREESTANDING",
    ):
        require(snippet in fixture, f"aio_error fixture omits {snippet}")
    start = (
        ROOT / "compat" / "x86_64" / "libc_aio_error_start.S"
    ).read_text(encoding="utf-8")
    for snippet in ("crabc_x86_64_aio_error_probe", "mov $60, %eax"):
        require(snippet in start, f"aio_error static entry omits {snippet}")
    require("ARCH_SET_FS" not in start, "aio_error static entry must not bootstrap TLS")

    runner = (
        ROOT / "compat" / "x86_64" / "run_libc_aio_error.sh"
    ).read_text(encoding="utf-8")
    for snippet in (
        "run_aio_error_header_abi.sh",
        "AARCH64_STATIC_TSV",
        "aio.lo",
        "aio.c",
        "assert_selected_c_abi_surface",
        "extract_selected_member",
        "aio_error archive member also defines an AIO operation sibling",
        "-nostdlib -static",
        '"$selected_member" -o "$candidate"',
        "candidate unexpectedly selects TLS",
        "never from libc.a",
        "aio_cancel aio_fsync aio_read aio_return aio_suspend aio_write",
        "__errno_location __h_errno_location h_errno getaddrinfo socket",
        "call|syscall",
    ):
        require(snippet in runner, f"aio_error runner omits {snippet}")
    require(
        '"$archive" -o "$candidate"' not in runner,
        "aio_error final candidate must not link libc.a",
    )

    oracle = artifact.get("oracle")
    require(isinstance(oracle, list), "static-c-aio-error needs oracle evidence")
    require(
        any(
            isinstance(entry, Mapping)
            and entry.get("kind") == "c-posix"
            and isinstance(entry.get("role"), str)
            and "src/aio/aio.c::aio_error" in entry["role"]
            and "a_barrier" in entry["role"]
            and "0x80000000" in entry["role"]
            for entry in oracle
        ),
        "static-c-aio-error must retain its pinned-musl observation oracle",
    )
    require(
        any(
            isinstance(entry, Mapping)
            and entry.get("kind") == "elf-abi"
            and isinstance(entry.get("role"), str)
            and "LP64" in entry["role"]
            and "archive-free static final-ELF boundary" in entry["role"]
            for entry in oracle
        ),
        "static-c-aio-error must retain its static ELF ABI oracle",
    )

    evidence = artifact.get("native_evidence")
    require(isinstance(evidence, list), "static-c-aio-error needs evidence")
    require(
        {entry.get("command") for entry in evidence if isinstance(entry, Mapping)}
        == {"./scripts/dev-x86_64.sh libc-aio-error"},
        "static-c-aio-error must use the closed libc-aio-error command",
    )
    scope = evidence[0].get("scope")
    require(isinstance(scope, str), "static-c-aio-error evidence needs a scope")
    for phrase in (
        "GNU-profile C/C++ <aio.h> header proof",
        "true x86 `-nostdlib -static` candidate",
        "`aio.lo` source mapping",
        "one extracted `aio_error` object",
        "never `libc.a`",
        "x86 compiler-only barrier",
        "168-byte align-8 aiocb/volatile __err offset 112 ABI",
        "zero/positive/sign-bit error mask behavior",
        "no interpreter/DT_NEEDED/unresolved symbol/dynamic-TLS model",
        "calls/syscalls",
        "AIO request submission",
        "aio_return",
        "resolver/DNS/netdb",
        "public x86 support",
    ):
        require(phrase in scope, f"static-c-aio-error evidence omits {phrase}")

    dispatch = (ROOT / "scripts" / "dev-x86_64.sh").read_text(encoding="utf-8")
    require(
        "aio-error-header-abi)" in dispatch
        and "run_aio_error_header_abi.sh" in dispatch
        and "libc-aio-error)" in dispatch
        and "run_libc_aio_error.sh" in dispatch,
        "aio_error dispatcher bindings are missing",
    )


def require_string_copy_artifact(family: Mapping[str, Any]) -> None:
    """Keep the stateless C-string-copy artifact identity and scope durable."""
    artifacts = require_verified_artifacts(
        family.get("verified_artifact"),
        "family[libc.posix-runtime].verified_artifact",
        family.get("status", ""),
    )
    matching = [entry for entry in artifacts if entry.get("id") == "static-c-string-copy"]
    require(
        len(matching) == 1,
        "libc.posix-runtime must contain exactly one static-c-string-copy artifact",
    )
    artifact = matching[0]
    description = artifact["description"]
    assert isinstance(description, str)
    for symbol in STRING_COPY_SYMBOLS:
        require(symbol in description, f"static-c-string-copy description omits {symbol}")
    for phrase in (
        "private `__stpcpy`/`__stpncpy` helpers",
        "stateless",
        "allocation-free",
        "scalar fallback",
    ):
        require(phrase in description, f"static-c-string-copy description omits {phrase}")
    evidence = artifact["native_evidence"]
    assert isinstance(evidence, list)
    require(
        {entry["command"] for entry in evidence}
        == {"./scripts/dev-x86_64.sh libc-string-copy"},
        "static-c-string-copy must use the closed libc-string-copy command",
    )
    header_prerequisites = nonempty_strings(
        artifact["x86_header_prerequisites"],
        "static-c-string-copy.x86_header_prerequisites",
    )
    require(
        any(
            "strdupa" in item
            and "caller-provided `alloca.h`" in item
            and "source-faithful C++" in item
            and "header-only" in item
            for item in header_prerequisites
        ),
        "static-c-string-copy must retain the header-only strdupa boundary",
    )


def require_error_strings_artifact(family: Mapping[str, Any]) -> None:
    """Keep the immutable error-string block complete but non-promoting."""
    artifacts = require_verified_artifacts(
        family.get("verified_artifact"),
        "family[libc.c-abi-compat].verified_artifact",
        family.get("status", ""),
    )
    matching = [
        entry for entry in artifacts if entry.get("id") == "static-c-error-strings"
    ]
    require(
        len(matching) == 1,
        "libc.c-abi-compat must contain exactly one static-c-error-strings artifact",
    )
    require(
        family.get("status") == "planned",
        "static-c-error-strings must not promote libc.c-abi-compat",
    )
    artifact = matching[0]
    require(
        "capabilities" not in artifact,
        "static-c-error-strings must not claim error.reporting-termination",
    )
    description = artifact["description"]
    assert isinstance(description, str)
    for symbol in ERROR_STRING_SYMBOLS:
        require(
            f"`{symbol}`" in description,
            f"static-c-error-strings description omits {symbol}",
        )
    for phrase in (
        "still-planned `libc.c-abi-compat`",
        "immutable fixed-C-locale lookup",
        "0 through 133",
        "one-past-table 134",
        "`No error information`",
        "ERANGE",
        "weak same-address",
        "does not claim the broader `error.reporting-termination`",
        "negative-input musl undefined behavior",
        "`strerror_l`/`__strerror_l`",
        "errno TLS",
        "`abort`",
        "variadic `syscall`",
        "public x86 support",
    ):
        require(
            phrase in description,
            f"static-c-error-strings description omits {phrase}",
        )

    owners = set(
        nonempty_strings(
            artifact["source_owners"], "static-c-error-strings.source_owners"
        )
    )
    for owner in (
        "libc/src/c_abi/x86_64/error_strings.rs",
        "include/string.h",
        "compat/x86_64/error_strings_header_abi_probe.c",
        "compat/x86_64/error_strings_header_abi_probe.cpp",
        "compat/x86_64/run_error_strings_header_abi.sh",
        "compat/x86_64/static_c_abi_exports.txt",
        "compat/x86_64/libc_error_strings_probe.c",
        "compat/x86_64/libc_error_strings_start.S",
        "compat/x86_64/run_libc_error_strings.sh",
        "compat/x86_64/tests/test_parity_ledger.py",
        "compat/x86_64/tests/test_runner.py",
        "compat/x86_64/validate_parity_ledger.py",
        "scripts/dev-x86_64.sh",
        "scripts/check_structure.py",
    ):
        require(owner in owners, f"static-c-error-strings source owners omit {owner}")

    prerequisites = nonempty_strings(
        artifact["x86_abi_prerequisites"],
        "static-c-error-strings.x86_abi_prerequisites",
    )
    require(
        any(
            "src/errno/__strerror.h" in item
            and "0 through 133" in item
            and "134" in item
            and "negative values" in item
            for item in prerequisites
        ),
        "static-c-error-strings must record its complete musl lookup domain",
    )
    require(
        any(
            "src/string/strerror_r.c" in item
            and "capacity-minus-one" in item
            and "ERANGE=34" in item
            and "Zero capacity" in item
            for item in prerequisites
        ),
        "static-c-error-strings must record its caller-buffer contract",
    )
    require(
        any(
            "weak_alias(strerror_r, __xpg_strerror_r)" in item
            and "no PT_TLS" in item
            and "ambient libc/compiler runtime" in item
            for item in prerequisites
        ),
        "static-c-error-strings must record its alias and sealed ELF boundary",
    )

    header_prerequisites = nonempty_strings(
        artifact["x86_header_prerequisites"],
        "static-c-error-strings.x86_header_prerequisites",
    )
    require(
        any(
            "C11/C++17 matrix" in item
            and "unconditional `char *strerror(int)`" in item
            and "POSIX/XOPEN/GNU/BSD-selected" in item
            and "strict-profile hiding" in item
            and "unmangled C++ linkage" in item
            and "absent from public headers" in item
            for item in header_prerequisites
        ),
        "static-c-error-strings must retain its public-header visibility contract",
    )

    static_exports = static_c_abi_export_names(
        ROOT / "compat" / "x86_64" / "static_c_abi_exports.txt"
    )
    require(
        set(ERROR_STRING_SYMBOLS) <= set(static_exports),
        "static-c-error-strings must be included in the selected export ratchet",
    )
    evidence = artifact["native_evidence"]
    assert isinstance(evidence, list)
    require(
        {entry["command"] for entry in evidence}
        == {"./scripts/dev-x86_64.sh libc-error-strings"},
        "static-c-error-strings must use the closed libc-error-strings command",
    )
    scope = evidence[0]["scope"]
    assert isinstance(scope, str)
    for phrase in (
        "0..=134",
        "ERANGE/NUL/untouched tails",
        "weak same-address __xpg_strerror_r",
        "rejects PT_TLS",
        "error.reporting-termination",
        "libc.c-abi-compat",
        "public x86 support",
    ):
        require(
            phrase in scope,
            f"static-c-error-strings evidence scope omits {phrase}",
        )


def require_l64a_artifact(family: Mapping[str, Any]) -> None:
    """Keep the source-split shared radix-64 result buffer private and exact."""
    artifacts = require_verified_artifacts(
        family.get("verified_artifact"),
        "family[libc.c-abi-compat].verified_artifact",
        family.get("status", ""),
    )
    matching = [entry for entry in artifacts if entry.get("id") == "static-c-l64a"]
    require(
        len(matching) == 1,
        "libc.c-abi-compat must contain exactly one static-c-l64a artifact",
    )
    require(
        family.get("status") == "planned",
        "static-c-l64a must not promote libc.c-abi-compat",
    )
    artifact = matching[0]
    require(
        "capabilities" not in artifact,
        "static-c-l64a must not alter Rust-facade or legacy.misc capability accounting",
    )

    description = artifact.get("description")
    require(isinstance(description, str), "static-c-l64a needs a description")
    for phrase in (
        "Private native x86 selected-static-archive `l64a` artifact",
        "still-planned `libc.c-abi-compat`",
        "one-symbol Rust archive member",
        "true `-nostdlib -static` candidate",
        "low-32-bit radix-64 encoder",
        "at most six",
        "static char s[7]",
        "shared `src/misc/a64l.c` and `a64l.lo` also define the state-free `a64l` decoder",
        "Strict/POSIX C/C++ hides",
        "X/Open 700, GNU, and BSD",
        "non-reentrant",
        "errno, TLS, locale, allocator, syscall, or runtime edge",
        "Rust-facade `numeric.scalar-legacy-callback` accounting",
        "complete `legacy.misc`",
        "general numeric parsing/conversion",
        "family completion, promotion, or public x86 support",
    ):
        require(phrase in description, f"static-c-l64a description omits {phrase}")

    owners = set(
        nonempty_strings(artifact.get("source_owners"), "static-c-l64a.source_owners")
    )
    for owner in (
        "compat/upstreams.toml",
        "compat/crabc-rs/coverage.toml",
        "libc/Cargo.toml",
        "libc/src/lib.rs",
        "libc/src/c_abi/x86_64/static_c_abi.rs",
        "libc/src/c_abi/x86_64/l64a.rs",
        "include/features.h",
        "include/bits/alltypes.h",
        "include/stdlib.h",
        "compat/abi/musl-1.2.6/aarch64/libc.a.static.tsv",
        "compat/x86_64/l64a_header_abi_probe.c",
        "compat/x86_64/l64a_header_abi_probe.cpp",
        "compat/x86_64/run_l64a_header_abi.sh",
        "compat/x86_64/static_c_abi_exports.txt",
        "compat/x86_64/libc_l64a_probe.c",
        "compat/x86_64/libc_l64a_start.S",
        "compat/x86_64/run_libc_l64a.sh",
        "compat/x86_64/aarch64_parity_inventory.py",
        "compat/x86_64/aarch64_parity_inventory.json",
        "compat/x86_64/tests/test_aarch64_parity_inventory.py",
        "compat/x86_64/tests/test_parity_ledger.py",
        "compat/x86_64/tests/test_runner.py",
        "compat/x86_64/validate_parity_ledger.py",
        "compat/x86_64/README.md",
        "STATUS.md",
        "x86-64.md",
        "scripts/dev-x86_64.sh",
        "scripts/check_structure.py",
    ):
        require(owner in owners, f"static-c-l64a source owners omit {owner}")

    prerequisites = nonempty_strings(
        artifact.get("x86_abi_prerequisites"), "static-c-l64a.x86_abi_prerequisites"
    )
    require(
        any(
            "SysV AMD64 LP64" in item
            and "rdi" in item
            and "rax" in item
            and "low 32 bits" in item
            and "seven-byte" in item
            for item in prerequisites
        ),
        "static-c-l64a must record its exact x86 C ABI",
    )
    require(
        any(
            "9fa28ece75d8a2191de7c5bb53bed224c5947417" in item
            and "src/misc/a64l.c::l64a" in item
            and "l64a.rs" in item
            and "a64l.lo" in item
            and "DIGITS" in item
            and "remaining as u32" in item
            and "*p = digits[x & 63]; x >>= 6; *p = 0" in item
            for item in prerequisites
        ),
        "static-c-l64a must retain its pinned-musl source split and mapping",
    )
    require(
        any(
            "same-address successive calls" in item
            and "externally synchronize" in item
            and "not TLS" in item
            and "allocation" in item
            for item in prerequisites
        ),
        "static-c-l64a must retain its shared-buffer caller-ownership boundary",
    )

    headers = nonempty_strings(
        artifact.get("x86_header_prerequisites"), "static-c-l64a.x86_header_prerequisites"
    )
    require(
        any(
            "C11/C++17" in item
            and "strict C/C++ and POSIX.1-2008 hide" in item
            and "X/Open 700, GNU, and BSD" in item
            and "unmangled C++ linkage" in item
            and "-nostdinc" in item
            for item in headers
        ),
        "static-c-l64a must retain its installed-header ABI boundary",
    )

    exports = set(
        static_c_abi_export_names(
            ROOT / "compat" / "x86_64" / "static_c_abi_exports.txt"
        )
    )
    require(
        set(L64A_SYMBOLS) <= exports,
        "static-c-l64a must retain its one selected export",
    )

    static_root = (
        ROOT / "libc" / "src" / "c_abi" / "x86_64" / "static_c_abi.rs"
    ).read_text(encoding="utf-8")
    require(
        '#[path = "l64a.rs"]\nmod l64a;' in static_root,
        "x86 static C ABI must compose the l64a leaf",
    )
    implementation = (
        ROOT / "libc" / "src" / "c_abi" / "x86_64" / "l64a.rs"
    ).read_text(encoding="utf-8")
    for snippet in (
        "musl 1.2.6",
        "9fa28ece75d8a2191de7c5bb53bed224c5947417",
        "src/misc/a64l.c",
        "a64l.lo",
        "seven-byte",
        "DIGITS",
        "L64A_RESULT",
        "remaining = value as u32",
        'pub unsafe extern "C" fn l64a',
        "must externally synchronize access",
    ):
        require(snippet in implementation, f"l64a leaf omits {snippet}")
    static_mut_names = re.findall(r"(?m)^static mut (\w+)", implementation)
    require(
        static_mut_names == ["L64A_RESULT"],
        "l64a must own exactly one shared seven-byte static mutable result buffer",
    )
    l64a_exports = set(
        re.findall(
            r'(?m)^pub\s+(?:unsafe\s+)?extern\s+"C"\s+fn\s+(\w+)\s*\(',
            implementation,
        )
    )
    require(l64a_exports == {"l64a"}, "l64a leaf must export only l64a")
    for forbidden in (
        "raw_syscall",
        "errno::",
        "__errno_location",
        "thread_local",
        "crabc_core",
        "crabc_mimalloc",
        "alloc::",
    ):
        require(
            forbidden not in implementation,
            f"l64a leaf widens into {forbidden}",
        )

    header_runner = (
        ROOT / "compat" / "x86_64" / "run_l64a_header_abi.sh"
    ).read_text(encoding="utf-8")
    for snippet in (
        "CANDIDATE_CC=/usr/bin/gcc",
        "-nostdinc",
        "-nostdinc++",
        "CRABC_REQUIRE_L64A_HIDDEN",
        "-D_POSIX_C_SOURCE=200809L",
        "-D_XOPEN_SOURCE=700",
        "-D_GNU_SOURCE",
        "-D_BSD_SOURCE",
        "retain C linkage",
        "escaped its declared roots",
    ):
        require(snippet in header_runner, f"l64a header runner omits {snippet}")
    for probe_name in ("l64a_header_abi_probe.c", "l64a_header_abi_probe.cpp"):
        probe = (ROOT / "compat" / "x86_64" / probe_name).read_text(encoding="utf-8")
        for snippet in ("l64a", "char *", "CRABC_EXPECT_L64A"):
            require(snippet in probe, f"l64a header probe {probe_name} omits {snippet}")

    fixture = (ROOT / "compat" / "x86_64" / "libc_l64a_probe.c").read_text(
        encoding="utf-8"
    )
    for snippet in (
        "CRABC_L64A_FREESTANDING",
        "check_alphabet_and_order",
        "check_low_32_bits",
        "check_shared_buffer",
        "errno = E2BIG",
    ):
        require(snippet in fixture, f"l64a fixture omits {snippet}")
    runner = (ROOT / "compat" / "x86_64" / "run_libc_l64a.sh").read_text(
        encoding="utf-8"
    )
    for snippet in (
        "a64l.lo",
        "run_l64a_header_abi.sh",
        "-nostdlib -static",
        "--no-undefined",
        "seven-byte mutable static result buffer",
        "call|syscall",
        "a64l strchr",
        "strtol strtoul strtoimax",
    ):
        require(snippet in runner, f"l64a runner omits {snippet}")

    evidence = artifact.get("native_evidence")
    require(isinstance(evidence, list), "static-c-l64a needs evidence")
    require(
        {entry.get("command") for entry in evidence if isinstance(entry, Mapping)}
        == {"./scripts/dev-x86_64.sh libc-l64a"},
        "static-c-l64a must use the closed libc-l64a command",
    )
    scope = evidence[0].get("scope")
    require(isinstance(scope, str), "static-c-l64a evidence needs a scope")
    for phrase in (
        "Pinned-musl project-header X/Open C execution",
        "shared `a64l.lo` provenance",
        "one-member `-nostdlib -static` candidate",
        "low-32-bit truncation",
        "same-address overwrite",
        "reference-only stale errno",
        "both `l64a`/`a64l`",
        "seven-byte mutable result object",
        "TLS/errno",
        "byte-string or numeric-parsing helpers",
        "Rust-facade accounting",
        "legacy.misc/general numeric conversion",
        "public x86 support",
    ):
        require(phrase in scope, f"static-c-l64a evidence omits {phrase}")

    oracle = artifact.get("oracle")
    require(isinstance(oracle, list), "static-c-l64a needs an oracle")
    require(
        any(
            isinstance(entry, Mapping)
            and entry.get("kind") == "c-posix"
            and "src/misc/a64l.c::l64a" in str(entry.get("role"))
            and "same-address overwrite" in str(entry.get("role"))
            and "no errno" in str(entry.get("role"))
            for entry in oracle
        ),
        "static-c-l64a must retain its musl behavior oracle",
    )
    require(
        any(
            isinstance(entry, Mapping)
            and entry.get("kind") == "elf-abi"
            and "rdi" in str(entry.get("role"))
            and "rax" in str(entry.get("role"))
            and "BSS" in str(entry.get("role"))
            for entry in oracle
        ),
        "static-c-l64a must retain its SysV ABI oracle",
    )

    dispatcher = (ROOT / "scripts" / "dev-x86_64.sh").read_text(encoding="utf-8")
    for snippet in ("l64a-header-abi)", "libc-l64a)"):
        require(snippet in dispatcher, f"x86 dispatcher omits {snippet}")


def require_a64l_artifact(family: Mapping[str, Any]) -> None:
    """Keep the opt-in radix-64 decoder source split and stateless."""
    artifacts = require_verified_artifacts(
        family.get("verified_artifact"),
        "family[libc.c-abi-compat].verified_artifact",
        family.get("status", ""),
    )
    matching = [entry for entry in artifacts if entry.get("id") == "static-c-a64l"]
    require(
        len(matching) == 1,
        "libc.c-abi-compat must contain exactly one static-c-a64l artifact",
    )
    require(
        family.get("status") == "planned",
        "static-c-a64l must not promote libc.c-abi-compat",
    )
    artifact = matching[0]
    require(
        "capabilities" not in artifact,
        "static-c-a64l must not alter Rust-facade or legacy.misc capability accounting",
    )

    description = artifact.get("description")
    require(isinstance(description, str), "static-c-a64l needs a description")
    for phrase in (
        "Private native x86 opt-in `a64l` selected-static-archive artifact",
        "still-planned `libc.c-abi-compat`",
        "`x86-a64l` feature adds exactly `a64l`",
        "true `-nostdlib -static` candidate",
        "at most six caller bytes",
        "uint32_t",
        "int32_t",
        "shared `src/misc/a64l.c` and `a64l.lo` also define `l64a`",
        "strchr(digits, *s)",
        "fixed 64-byte alphabet",
        "Strict/POSIX C/C++ hides `a64l`",
        "unmangled `long(const char *)` linkage",
        "no mutable state, errno, TLS, locale, allocator, syscall, or runtime edge",
        "does not complete `legacy.misc` or general numeric parsing/conversion",
        "family completion, promotion, or public x86 support",
    ):
        require(phrase in description, f"static-c-a64l description omits {phrase}")

    owners = set(
        nonempty_strings(artifact.get("source_owners"), "static-c-a64l.source_owners")
    )
    for owner in (
        "compat/upstreams.toml",
        "compat/crabc-rs/coverage.toml",
        "libc/Cargo.toml",
        "libc/src/lib.rs",
        "libc/src/c_abi/x86_64/static_c_abi.rs",
        "libc/src/c_abi/x86_64/a64l.rs",
        "include/features.h",
        "include/bits/alltypes.h",
        "include/stdlib.h",
        "compat/abi/musl-1.2.6/aarch64/libc.a.static.tsv",
        "compat/x86_64/l64a_header_abi_probe.c",
        "compat/x86_64/l64a_header_abi_probe.cpp",
        "compat/x86_64/run_l64a_header_abi.sh",
        "compat/x86_64/static_c_abi_exports.txt",
        "compat/x86_64/libc_a64l_probe.c",
        "compat/x86_64/libc_a64l_start.S",
        "compat/x86_64/run_libc_a64l.sh",
        "compat/x86_64/tests/test_a64l.py",
        "compat/x86_64/tests/test_parity_ledger.py",
        "compat/x86_64/tests/test_runner.py",
        "compat/x86_64/validate_parity_ledger.py",
        "compat/x86_64/README.md",
        "STATUS.md",
        "scripts/dev-x86_64.sh",
        "scripts/check_structure.py",
    ):
        require(owner in owners, f"static-c-a64l source owners omit {owner}")
    require(
        "libc/src/c_abi/x86_64/byte_strings.rs" not in owners,
        "static-c-a64l must not select the broad byte-string archive owner",
    )

    prerequisites = nonempty_strings(
        artifact.get("x86_abi_prerequisites"), "static-c-a64l.x86_abi_prerequisites"
    )
    require(
        any(
            "SysV AMD64 LP64" in item
            and "rdi" in item
            and "rax" in item
            and "six non-NUL" in item
            and "int32_t" in item
            for item in prerequisites
        ),
        "static-c-a64l must record its exact x86 C ABI",
    )
    require(
        any(
            "9fa28ece75d8a2191de7c5bb53bed224c5947417" in item
            and "src/misc/a64l.c::a64l" in item
            and "a64l.rs" in item
            and "a64l.lo" in item
            and "strchr(digits, *s)" in item
            and "local bounded scan" in item
            and "64-byte `DIGITS`" in item
            for item in prerequisites
        ),
        "static-c-a64l must retain its pinned-musl mapping and intentional scan",
    )
    require(
        any(
            "exactly public `a64l`" in item
            and "no direct undefined runtime dependency" in item
            and "no l64a result object" in item
            and "byte-string helper" in item
            for item in prerequisites
        ),
        "static-c-a64l must retain its one-owner dependency boundary",
    )

    headers = nonempty_strings(
        artifact.get("x86_header_prerequisites"), "static-c-a64l.x86_header_prerequisites"
    )
    require(
        any(
            "C11/C++17" in item
            and "hide both `a64l` and `l64a`" in item
            and "X/Open 700, GNU, and BSD" in item
            and "long(const char *)" in item
            and "-nostdinc" in item
            for item in headers
        ),
        "static-c-a64l must retain the shared installed-header ABI boundary",
    )

    exports = set(
        static_c_abi_export_names(
            ROOT / "compat" / "x86_64" / "static_c_abi_exports.txt"
        )
    )
    require(
        "a64l" not in exports,
        "static-c-a64l must remain absent from the frozen default export contract",
    )

    static_root = (
        ROOT / "libc" / "src" / "c_abi" / "x86_64" / "static_c_abi.rs"
    ).read_text(encoding="utf-8")
    require(
        '#[cfg(feature = "x86-a64l")]\n#[path = "a64l.rs"]\nmod a64l;' in static_root,
        "x86 static C ABI must compose a64l only through its opt-in feature",
    )
    implementation = (
        ROOT / "libc" / "src" / "c_abi" / "x86_64" / "a64l.rs"
    ).read_text(encoding="utf-8")
    for snippet in (
        "Pinned musl 1.2.6",
        "9fa28ece75d8a2191de7c5bb53bed224c5947417",
        "src/misc/a64l.c::a64l",
        "a64l.lo",
        "equivalent bounded scan",
        "DIGITS",
        "while index < 64",
        "for shift in (0..36).step_by(6)",
        'pub unsafe extern "C" fn a64l',
        "# Safety",
    ):
        require(snippet in implementation, f"a64l leaf omits {snippet}")
    a64l_exports = set(
        re.findall(
            r'(?m)^pub\s+(?:unsafe\s+)?extern\s+"C"\s+fn\s+(\w+)\s*\(',
            implementation,
        )
    )
    require(a64l_exports == {"a64l"}, "a64l leaf must export only a64l")
    for forbidden in (
        "static mut",
        "unsafe extern \"C\" {",
        "raw_syscall",
        "errno::",
        "__errno_location",
        "thread_local",
        "crabc_core",
        "crabc_mimalloc",
        "alloc::",
    ):
        require(forbidden not in implementation, f"a64l leaf widens into {forbidden}")

    header_runner = (
        ROOT / "compat" / "x86_64" / "run_l64a_header_abi.sh"
    ).read_text(encoding="utf-8")
    for snippet in (
        "a64l/l64a",
        "CANDIDATE_CC=/usr/bin/gcc",
        "-nostdinc",
        "-nostdinc++",
        "CRABC_REQUIRE_L64A_HIDDEN",
        "CRABC_REQUIRE_A64L_HIDDEN",
        "CRABC_EXPECT_A64L",
        "unmangled a64l",
        "-D_POSIX_C_SOURCE=200809L",
        "-D_XOPEN_SOURCE=700",
        "-D_GNU_SOURCE",
        "-D_BSD_SOURCE",
        "escaped its declared roots",
    ):
        require(snippet in header_runner, f"a64l header runner omits {snippet}")
    for probe_name in ("l64a_header_abi_probe.c", "l64a_header_abi_probe.cpp"):
        probe = (ROOT / "compat" / "x86_64" / probe_name).read_text(encoding="utf-8")
        for snippet in ("a64l", "long", "const char *", "CRABC_EXPECT_A64L"):
            require(snippet in probe, f"a64l header probe {probe_name} omits {snippet}")

    fixture = (ROOT / "compat" / "x86_64" / "libc_a64l_probe.c").read_text(
        encoding="utf-8"
    )
    for snippet in (
        "CRABC_A64L_FREESTANDING",
        "check_alphabet",
        "check_bit_packing",
        "check_invalid_and_bound",
        "nul_with_suffix",
        "check_signed_result",
        "check_input_is_unchanged",
        '".....0"',
        "errno = E2BIG",
    ):
        require(snippet in fixture, f"a64l fixture omits {snippet}")
    runner = (ROOT / "compat" / "x86_64" / "run_libc_a64l.sh").read_text(
        encoding="utf-8"
    )
    for snippet in (
        "x86-a64l",
        "a64l.lo",
        "run_l64a_header_abi.sh",
        "assert_feature_delta",
        "a64l\\n",
        "-nostdlib -static",
        "--gc-sections",
        "a64l owner has an unexpected direct dependency",
        "call|syscall",
        "l64a|strchr|index|memchr",
    ):
        require(snippet in runner, f"a64l runner omits {snippet}")
    require("--whole-archive" not in runner, "a64l runner must not whole-archive")

    evidence = artifact.get("native_evidence")
    require(isinstance(evidence, list), "static-c-a64l needs evidence")
    require(
        {entry.get("command") for entry in evidence if isinstance(entry, Mapping)}
        == {"./scripts/dev-x86_64.sh libc-a64l"},
        "static-c-a64l must use the closed libc-a64l command",
    )
    scope = evidence[0].get("scope")
    require(isinstance(scope, str), "static-c-a64l evidence needs a scope")
    for phrase in (
        "Pinned-musl project-header X/Open C execution",
        "shared `a64l.lo` provenance",
        "one-member `-nostdlib -static` candidate",
        "every alphabet position",
        "first-invalid and high-byte stopping",
        "signed `int32_t` result",
        "exactly a64l",
        "no-dependency/no-call decoder owner",
        "does not complete legacy.misc or general numeric parsing/conversion",
        "public x86 support",
    ):
        require(phrase in scope, f"static-c-a64l evidence omits {phrase}")

    oracle = artifact.get("oracle")
    require(isinstance(oracle, list), "static-c-a64l needs an oracle")
    require(
        any(
            isinstance(entry, Mapping)
            and entry.get("kind") == "c-posix"
            and "src/misc/a64l.c::a64l" in str(entry.get("role"))
            and "strchr" in str(entry.get("role"))
            and "local 64-byte table scan" in str(entry.get("role"))
            and "no errno" in str(entry.get("role"))
            for entry in oracle
        ),
        "static-c-a64l must retain its musl behavior oracle",
    )
    require(
        any(
            isinstance(entry, Mapping)
            and entry.get("kind") == "elf-abi"
            and "rdi" in str(entry.get("role"))
            and "rax" in str(entry.get("role"))
            and "one-owner" in str(entry.get("role"))
            for entry in oracle
        ),
        "static-c-a64l must retain its SysV ABI oracle",
    )

    dispatcher = (ROOT / "scripts" / "dev-x86_64.sh").read_text(encoding="utf-8")
    for snippet in ("l64a-header-abi)", "libc-a64l)"):
        require(snippet in dispatcher, f"x86 dispatcher omits {snippet}")


def require_error_strsignal_slice(family: Mapping[str, Any]) -> None:
    """Keep the fixed-profile strsignal selection bounded and non-promoting."""
    slices = require_verified_slices(
        family.get("verified_slice"),
        "family[libc.c-abi-compat].verified_slice",
        family.get("status", ""),
        list(family.get("capabilities", [])),
    )
    matching = [entry for entry in slices if entry.get("id") == "error.strsignal"]
    require(len(matching) == 1, "libc.c-abi-compat needs one error.strsignal slice")
    require(
        family.get("status") == "planned",
        "strsignal selection must not promote libc.c-abi-compat",
    )
    selected = matching[0]
    require(
        selected["capabilities"] == ["error.reporting-termination"],
        "strsignal slice must select exactly error.reporting-termination",
    )
    description = selected["description"]
    assert isinstance(description, str)
    for phrase in (
        "still-planned `libc.c-abi-compat`",
        "strong `strsignal`",
        "C/POSIX/C.UTF-8",
        "1 through 64",
        "`SIGHUP..SIGSYS == 1..31`",
        "`RT32` through `RT64`",
        "`Unknown signal`",
        "`strerror`/`strerror_l`",
        "`psignal`",
        "process termination",
        "general diagnostics",
        "promotion/public_support=false",
        "public x86 support",
    ):
        require(phrase in description, f"error.strsignal description omits {phrase}")

    owners = set(
        nonempty_strings(selected["source_owners"], "error.strsignal.source_owners")
    )
    for owner in (
        "compat/upstreams.toml",
        "libc/Cargo.toml",
        "libc/src/lib.rs",
        "libc/src/c_abi/x86_64/static_c_abi.rs",
        "libc/src/c_abi/x86_64/strsignal.rs",
        "include/string.h",
        "compat/abi/musl-1.2.6/aarch64/libc.a.static.tsv",
        "compat/x86_64/static_c_abi_exports.txt",
        "compat/x86_64/strsignal_header_abi_probe.c",
        "compat/x86_64/strsignal_header_abi_probe.cpp",
        "compat/x86_64/run_strsignal_header_abi.sh",
        "compat/x86_64/libc_strsignal_probe.c",
        "compat/x86_64/libc_strsignal_start.S",
        "compat/x86_64/run_libc_strsignal.sh",
        "compat/x86_64/aarch64_parity_inventory.py",
        "compat/x86_64/aarch64_parity_inventory.json",
        "compat/x86_64/tests/test_parity_ledger.py",
        "compat/x86_64/tests/test_runner.py",
        "compat/x86_64/validate_parity_ledger.py",
        "compat/x86_64/README.md",
        "STATUS.md",
        "x86-64.md",
        "scripts/dev-x86_64.sh",
        "scripts/check_structure.py",
    ):
        require(owner in owners, f"error.strsignal source owners omit {owner}")

    prerequisites = nonempty_strings(
        selected["x86_abi_prerequisites"], "error.strsignal.x86_abi_prerequisites"
    )
    require(
        any(
            "SysV AMD64 LP64" in item
            and "signed 32-bit" in item
            and "eight-byte" in item
            for item in prerequisites
        ),
        "error.strsignal must record its scalar/pointer ABI",
    )
    require(
        any(
            "src/string/strsignal.c" in item
            and "SIGHUP..SIGSYS == 1..31" in item
            and "_NSIG == 65" in item
            and "RT32" in item
            and "RT64" in item
            for item in prerequisites
        ),
        "error.strsignal must record the musl signal-number map",
    )
    require(
        any(
            "LCTRANS_CUR" in item
            and "C/POSIX/C.UTF-8" in item
            and "no errno, TLS, lock, allocation, or syscall" in item
            for item in prerequisites
        ),
        "error.strsignal must retain its fixed-profile runtime boundary",
    )
    require(
        any(
            "no PT_TLS" in item
            and "ambient libc/compiler runtime" in item
            for item in prerequisites
        ),
        "error.strsignal must record its sealed static ELF boundary",
    )

    header_prerequisites = nonempty_strings(
        selected["x86_header_prerequisites"],
        "error.strsignal.x86_header_prerequisites",
    )
    require(
        any(
            "strict C/C++" in item
            and "POSIX/XOPEN/GNU/BSD" in item
            and "`char *strsignal(int)`" in item
            and "unmangled C++ linkage" in item
            for item in header_prerequisites
        ),
        "error.strsignal must pin its selected C/C++ header contract",
    )

    static_exports = static_c_abi_export_names(
        ROOT / "compat" / "x86_64" / "static_c_abi_exports.txt"
    )
    require(
        set(STRSIGNAL_SYMBOLS) <= set(static_exports),
        "error.strsignal must be included in the selected export ratchet",
    )
    static_root = (
        ROOT / "libc" / "src" / "c_abi" / "x86_64" / "static_c_abi.rs"
    ).read_text(encoding="utf-8")
    require(
        '#[path = "strsignal.rs"]\nmod strsignal;' in static_root,
        "x86 static C ABI must compose the bounded strsignal leaf",
    )
    source = (
        ROOT / "libc" / "src" / "c_abi" / "x86_64" / "strsignal.rs"
    ).read_text(encoding="utf-8")
    for snippet in (
        "src/string/strsignal.c",
        "SIGHUP..SIGSYS == 1..31",
        "MAX_SIGNAL_NUMBER: c_int = 64",
        "RT32",
        "RT64",
        "LCTRANS_CUR",
        "pub extern \"C\" fn strsignal",
    ):
        require(snippet in source, f"error.strsignal source omits {snippet}")

    evidence = selected["native_evidence"]
    assert isinstance(evidence, list)
    require(
        {entry["command"] for entry in evidence}
        == {"./scripts/dev-x86_64.sh libc-strsignal"},
        "error.strsignal must use the closed libc-strsignal command",
    )
    scope = evidence[0]["scope"]
    assert isinstance(scope, str)
    for phrase in (
        "-4..=68",
        "RT32..RT64",
        "shared unknown storage",
        "strerror/strerror_l",
        "signal delivery/disposition",
        "process termination",
        "family promotion",
        "public x86 support",
    ):
        require(phrase in scope, f"error.strsignal evidence scope omits {phrase}")

    runner = (ROOT / "compat" / "x86_64" / "run_libc_strsignal.sh").read_text(
        encoding="utf-8"
    )
    fixture = (ROOT / "compat" / "x86_64" / "libc_strsignal_probe.c").read_text(
        encoding="utf-8"
    )
    header_runner = (
        ROOT / "compat" / "x86_64" / "run_strsignal_header_abi.sh"
    ).read_text(encoding="utf-8")
    for snippet in (
        "assert_selected_c_abi_surface",
        "assert_strong_function",
        "run_strsignal_header_abi.sh",
        "-nostdlib -static",
        "candidate unexpectedly selects TLS",
        "error strings, diagnostics, termination",
    ):
        require(snippet in runner, f"error.strsignal runner omits {snippet}")
    for snippet in (
        "strsignal-domain-fnv1a64",
        "signal_number = -4",
        "RT32",
        "RT64",
        "strsignal(-1) != strsignal(0)",
        "CRABC_STRSIGNAL_FREESTANDING",
    ):
        require(snippet in fixture, f"error.strsignal fixture omits {snippet}")
    for snippet in (
        "CRABC_EXPECT_STRSIGNAL",
        "CRABC_REQUIRE_STRSIGNAL_HIDDEN",
        "-std=c++17",
        "nm --undefined-only",
        "string.h",
    ):
        require(snippet in header_runner, f"error.strsignal header runner omits {snippet}")
    dispatcher = (ROOT / "scripts" / "dev-x86_64.sh").read_text(encoding="utf-8")
    for snippet in ("run_strsignal_header_abi.sh", "run_libc_strsignal.sh"):
        require(snippet in dispatcher, f"error.strsignal dispatcher omits {snippet}")


def require_ctype_artifact(family: Mapping[str, Any]) -> None:
    """Keep the fixed-C-locale ctype artifact identity and scope durable."""
    artifacts = require_verified_artifacts(
        family.get("verified_artifact"),
        "family[libc.posix-runtime].verified_artifact",
        family.get("status", ""),
    )
    matching = [entry for entry in artifacts if entry.get("id") == "static-c-ctype"]
    require(
        len(matching) == 1,
        "libc.posix-runtime must contain exactly one static-c-ctype artifact",
    )
    artifact = matching[0]
    description = artifact["description"]
    assert isinstance(description, str)
    for symbol in CTYPE_SYMBOLS:
        require(symbol in description, f"static-c-ctype description omits {symbol}")
    for phrase in (
        "fixed-C-locale ctype block",
        "stateless",
        "allocation-free",
        "`EOF` and every `unsigned char` value",
        "locale selection and `_l` entries",
    ):
        require(phrase in description, f"static-c-ctype description omits {phrase}")
    evidence = artifact["native_evidence"]
    assert isinstance(evidence, list)
    require(
        {entry["command"] for entry in evidence}
        == {"./scripts/dev-x86_64.sh libc-ctype"},
        "static-c-ctype must use the closed libc-ctype command",
    )


