                "scheduler mutation/parameters",
                "priority bounds",
                "POSIX sched_yield",
                "affinity",
                "pthread scheduling",
                "sched_getscheduler disassembly",
                "raw syscall 145",
                "raw-current/raw-invalid contrast",
                "C ABI -1/ENOSYS",
                "C11 thrd_yield and priority-bounds",
