        "libc/src/c_abi/x86_64/static_tls.rs",
        "include/errno.h",
        "include/signal.h",
        "include/bits/alltypes.h",
        "compat/x86_64/signal_header_abi_probe.c",
        "compat/x86_64/signal_header_posix_abi_probe.c",
