        "unspecified classification",
        "loopback/multicast/v4-compatible",
        "global default read-only 16-byte object",
        "no interpreter/DT_NEEDED/unresolved symbol",
        "TLS",
        "errno",
        "dynamic TLS",
        "call",
        "syscall",
        "in6addr_loopback",
