        "direct initial-exec errno TLS",
        "pinned-musl assignment-suppression evidence only",
        "unsuppressed string storage",
        "character suppression",
        "other suppression",
        "literal-percent",
        "format-whitespace",
        "`%n`/`%hhn` count-store",
        "scanset/pointer/integer/floating/wide",
