def require_stdio_permanent_fwritable_stderr_artifact(
    family: Mapping[str, Any],
) -> None:
    """Keep one fixed stderr extension query below general FILE access.

    Pinned musl reads only F_NOWR for __fwritable. The permanent stderr
    record fixes that flag absent, so the selected exact one result needs no
    cursor, I/O, or access-mode transition. This must stay a private GNU
    spelling rather than a general stdio-extension capability.
    """
    artifacts = require_verified_artifacts(
        family.get("verified_artifact"),
        "family[libc.text-math-locale-stdio].verified_artifact",
        family.get("status", ""),
    )
