    for symbol in ("rintl", "sqrtl"):
        require(
            f".global {symbol}" not in implementation,
            f"math_x87_extended leaf must not duplicate the selected {symbol} owner",
        )
    fenv_rounding = (
        ROOT / "libc" / "src" / "c_abi" / "x86_64" / "fenv_rounding.rs"
    ).read_text(encoding="utf-8")
